'use strict';
const $=s=>document.querySelector(s),esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const paths={updates:'M3 5h18v15H3z M3 6l9 7 9-7 M16 2v6 M13 5h6',ranks:'M12 2 21 7v10l-9 5-9-5V7z M8 9l4 3 4-3 M8 14l4 3 4-3',render:'M4 9h16v12H4z M4 9 2 4l17-3 2 5z M7 3l3 4 M14 2l3 4 M10 12l6 3-6 3z',edit:'M3 6h18v4H3z M3 14h12v4H3z M17 3v19',overview:'M3 3h7v7H3z M14 3h7v7h-7z M3 14h7v7H3z M14 14h7v7h-7z',focus:'M12 3a9 9 0 1 0 0 18 9 9 0 0 0 0-18 M12 7v5l3 2',stats:'M4 20V10 M10 20V4 M16 20v-8 M22 20H2',quests:'M9 5h11 M9 12h11 M9 19h11 M3 5l1 1 2-3 M3 12l1 1 2-3 M3 19l1 1 2-3',achievements:'M8 3h8v7a4 4 0 0 1-8 0z M8 5H4v3a4 4 0 0 0 4 4 M16 5h4v3a4 4 0 0 1-4 4 M12 14v5 M8 21h8',projects:'M3 6h7l2 3h9v11H3z',shop:'M3 8h18l-2-5H5z M4 8v13h16V8 M9 21v-7h6v7',profile:'M12 3a4 4 0 1 0 0 8 4 4 0 0 0 0-8 M4 21v-3a8 6 0 0 1 16 0v3',journal:'M4 3h16v18H4z M8 7h8 M8 11h8 M8 15h5',friends:'M9 4a3 3 0 1 0 0 6 3 3 0 0 0 0-6 M2 21v-4a7 5 0 0 1 14 0v4 M17 4a3 3 0 0 1 0 6 M19 13a5 5 0 0 1 3 5v3',settings:'M12 8a4 4 0 1 0 0 8 4 4 0 0 0 0-8 M12 2v3 M12 19v3 M2 12h3 M19 12h3 M5 5l2 2 M17 17l2 2 M5 19l2-2 M17 7l2-2'};
const icon=id=>`<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.5" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="${paths[id]||paths.overview}"/></svg>`;
const pages=[['overview','Resumen','Cada edición cuenta.'],['ranks','Rangos','Tu camino como editor.'],['focus','Modo enfoque','Solo tú y tu siguiente corte.'],['stats','Estadísticas','Tu constancia, en perspectiva.'],['quests','Retos y metas','Un objetivo. Un paso más.'],['achievements','Logros','Pequeños pasos. Grandes hitos.'],['projects','Proyectos','El tiempo detrás de cada historia.'],['shop','Tienda','Dale tu estilo al progreso.'],['profile','Mi perfil','Este es tu recorrido.'],['journal','Diario','Guarda lo que vas creando.'],['friends','Social','Ranking de editores'],['admin','Test de inventario','Test de inventario'],['updates','Novedades','Notas de actualización.'],['settings','Ajustes','A tu manera.']];
let state=null,page='overview',filter='all',shopFilter='all',search='',lastFull=0,toastTimer;
const fmt=n=>Math.floor(n||0).toLocaleString('es-MX');
const clock=n=>{n=Math.max(0,Math.floor(n||0));return `${String(Math.floor(n/3600)).padStart(2,'0')}:${String(Math.floor(n/60)%60).padStart(2,'0')}:${String(n%60).padStart(2,'0')}`;};
const hours=n=>((n||0)/3600).toLocaleString('es-MX',{maximumFractionDigits:1})+' h';
const money=n=>new Intl.NumberFormat('es-MX',{style:'currency',currency:state.settings.currency}).format(n||0);
const date=n=>new Date(n).toLocaleDateString('es-MX',{day:'numeric',month:'short'});
const progress=(n,max,lime=false)=>`<div class="progress ${lime?'lime':''}"><span style="width:${Math.max(0,Math.min(100,(n||0)/Math.max(1,max)*100))}%"></span></div>`;
const nameStyle=id=>{if(!id)return '';const palettes={rainbow:'#ff4b61,#ffb347,#ffe868,#58eaa5,#54c6ff,#b786ff,#ff4b61',rainbow_wave:'#ff4b61,#ffb347,#ffe868,#58eaa5,#54c6ff,#b786ff,#ff4b61',rgb_spectrum:'#ff3030,#42ff70,#397dff,#ff3030',pastel_cloud:'#ffc8e5,#d8c7ff,#b7e5ff,#c5f7db,#ffc8e5',sunset_glow:'#ff7b75,#ffbd6b,#d87df4,#ff7b75',arctic_ice:'#e8fbff,#63d7ff,#769aff,#e8fbff',neon_dream:'#ff41d7,#8a52ff,#37eeff,#ff41d7',rose_gold:'#ffd5cb,#f4a5a4,#ffe2bd,#ffd5cb',emerald_laser:'#35f5a0,#caff7d,#1cdaba,#35f5a0',fire:'#ffe873,#ff703b,#e53c65,#ffe873',ice:'#e6fdff,#83deff,#9dacf9,#e6fdff',mint:'#b0ffdd,#6cf2d0,#a0caff,#b0ffdd',peach:'#ffe0b9,#ff9ea6,#ffcaa5,#ffe0b9'};let n=0;for(const c of id)n=(n*31+c.charCodeAt(0))>>>0;const colors=palettes[id]||`hsl(${n%360} 90% 74%),hsl(${(n+100)%360} 85% 60%),hsl(${n%360} 90% 74%)`;return `background-image:linear-gradient(110deg,${colors});background-size:300% 100%;background-clip:text;-webkit-background-clip:text;color:transparent`;};
const rankImg=(name=state.rank.name,cls='rank-image')=>`<img class="${cls}" src="../assets/img/ranks-studio/${name.toLowerCase()}.svg" alt="${esc(name)}">`;
const section=(title,sub='',action='')=>`<div class="section-heading"><div><h2>${title}</h2>${sub?`<span class="muted small">${sub}</span>`:''}</div>${action}</div>`;
const btn=(text,action,value='',cls='')=>`<button class="button ${cls}" data-action="${action}" data-value="${esc(value)}">${text}</button>`;
const goto=(text,target)=>`<button class="button quiet" data-page="${target}">${text} ↗</button>`;
const empty=(title,description)=>`<div class="empty"><div class="big-icon">◇</div><h2>${title}</h2><p>${description}</p></div>`;
function toast(text){$('#toast').textContent=text;$('#toast').style.display='block';clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').style.display='none',5000);}
async function action(kind,value){const r=await window.ranked.action(kind,value);if(!r.ok){toast(r.error);return false;}if(r.state){state=r.state;render();}return true;}
function modal(html){$('#modal-body').innerHTML=html;$('#modal').showModal();}
$('#modal-close').onclick=()=>$('#modal').close();
$('#modal').addEventListener('close',async()=>{if(!$('#modal').dataset.releaseVersion)return;const version=$('#modal').dataset.releaseVersion;delete $('#modal').dataset.releaseVersion;const result=await window.ranked.action('readReleaseNotes',version);if(!result.ok)toast(result.error);else if(result.state){state=result.state;render();}});
function renderNavigation(){
 const available=pages;
 $('#nav').innerHTML=available.map(([id,name])=>`<button data-page="${id}">${icon(id)}<span>${name}</span></button>`).join('');
}
$('#pause').onclick=()=>action('pause');$('#avatar').onclick=()=>navigate('profile');
function navigate(p){page=p;filter='all';search='';render();window.scrollTo(0,0);}
function metrics(){return `<div class="grid four">${[['HOY',hours(state.daySeconds),`${state.settings.dailyMinutes} min de meta diaria`,'focus'],['ESTA SEMANA',hours(state.weekSeconds),`${state.settings.weeklyHours} h de meta semanal`,'stats'],['EXPERIENCIA TOTAL',fmt(state.xp)+' XP','Cada minuto suma','quests'],['RACHA ACTUAL',state.streak+' días','Récord: '+state.bestStreak+' días','achievements']].map(([label,n,foot,i])=>`<div class="card"><div class="row"><span class="metric-label">${label}</span><span class="metric-icon">${icon(i)}</span></div><div class="metric-number">${n}</div><span class="metric-foot">${foot}</span></div>`).join('')}</div>`;}
function quest(q){return `<div class="quest"><div class="row"><span class="quest-name">${q.done?'<span class="check">✓</span> ':''}${esc(q.title)}</span><span class="xp">+${q.reward} XP</span></div><div class="quest-desc">${esc(q.description||'Objetivo diario')} · ${fmt(Math.min(q.progress,q.goal))} / ${fmt(q.goal)}</div>${progress(q.progress,q.goal,q.done)}</div>`;}
function chart(days=7){const entries=[];const now=new Date();for(let i=days-1;i>=0;i--){const d=new Date(now.getFullYear(),now.getMonth(),now.getDate()-i);const key=d.getFullYear()+'-'+String(d.getMonth()+1).padStart(2,'0')+'-'+String(d.getDate()).padStart(2,'0');entries.push({d,n:state.dayLog[key]||0,today:i===0});}const max=Math.max(3600,...entries.map(x=>x.n));return `<div class="chart">${entries.map(x=>`<div class="chart-col"><div class="chart-value">${x.n?hours(x.n):'—'}</div><div class="bar-wrap"><div class="bar ${x.today?'today':''}" style="height:${Math.max(2,x.n/max*100)}%" title="${date(x.d)}: ${hours(x.n)}"></div></div><span class="chart-label">${days>7?x.d.getDate():x.d.toLocaleDateString('es-MX',{weekday:'short'}).replace('.','')}</span></div>`).join('')}</div>`;}
function activity(limit=5){return state.events.length?state.events.slice(0,limit).map(e=>`<div class="activity"><div class="activity-dot"></div><div><h3>${esc(e.title)}</h3><p>${esc(e.text)} ${e.xp?`<span class="xp">+${fmt(e.xp)} XP</span>`:''}</p></div><small>${date(e.at)}</small></div>`).join(''):empty('Tu historia empieza aquí','Abre Premiere y comienza a editar. Tus hitos aparecerán en este espacio.');}
const studioRanks=['IRON','BRONZE','SILVER','GOLD','PLATINUM','DIAMOND','ASCENDANT','IMMORTAL','RADIANT'];
function editorTimeline(){return `<div class="editor-timeline" aria-hidden="true"><div class="transport">◁ <span>▶</span> ▷</div><div class="time-ruler"><span>00:00</span><span>00:30</span><span>01:00</span><span>01:30</span></div><div class="track video"><i></i><i></i><i></i></div><div class="track titles"><i></i><i></i></div><div class="track audio"></div><div class="playhead"></div><small>ACTIVITÉ / TIMELINE</small></div>`;}
function studioProfile(){const mine=state.social?.rows?.find(r=>r.mine);return `<section class="card dashboard-profile"><div class="profile-cover" style="background-image:url('${esc(state.bannerGif||(state.cosmetics.banner?bannerUrl(state.cosmetics.banner):'premiere-workspace.svg'))}')"></div><h2>Tu perfil</h2><div class="profile-main"><div class="dashboard-avatar">${state.avatar?`<img src="${esc(state.avatar)}" alt="Foto de perfil">`:icon('profile')}</div><div class="profile-copy"><h3 class="${state.cosmetics.namefx?'animated-name':''}" style="${nameStyle(state.cosmetics.namefx)}">${esc(state.name)}</h3>${titleLabel()}<p class="muted">Editor desde hace ${fmt((Date.now()-state.created)/86400000)} días</p><div class="profile-rank">${rankImg()}<div><strong>Nivel ${state.level.level}</strong><span>${esc(state.rank.name)}</span></div></div></div>${mine?`<div class="profile-position"><span>♛</span><strong>#${fmt(mine.position)}</strong><small>en el ranking</small></div>`:''}</div><button class="profile-edit" data-page="profile">Personalizar perfil ↗</button></section>`;}
function studioMetrics(){const unlocked=state.achievements.filter(a=>a.unlocked).length;return `<div class="dashboard-metrics">${[['render','Exportaciones',fmt(state.stats.renders)],['focus','Tiempo total',hours(state.seconds)],['edit','Ediciones estimadas',fmt(state.stats.edits)],['quests','Racha actual',fmt(state.streak)+' días'],['achievements','Logros desbloqueados',unlocked+' / '+state.achievements.length]].map(([i,label,value])=>`<div class="card dashboard-metric"><div>${icon(i)}<span>${label}</span></div><strong>${value}</strong>${i==='achievements'?progress(unlocked,state.achievements.length):'<small>Registro de tu actividad</small>'}</div>`).join('')}</div>`;}
function activityGraph(){const entries=[];const now=new Date();for(let i=6;i>=0;i--){const d=new Date(now.getFullYear(),now.getMonth(),now.getDate()-i);const key=d.getFullYear()+'-'+String(d.getMonth()+1).padStart(2,'0')+'-'+String(d.getDate()).padStart(2,'0');entries.push({label:d.toLocaleDateString('es-MX',{weekday:'short'}),n:state.dayLog[key]||0});}const max=Math.max(3600,...entries.map(e=>e.n));const pts=entries.map((e,i)=>[50+i*95,180-e.n/max*145]);const line=pts.map(p=>p.join(',')).join(' ');return `<svg class="activity-graph" viewBox="0 0 660 220" role="img" aria-label="Tiempo de edición de los últimos siete días"><defs><linearGradient id="chart-fill" x1="0" y1="0" x2="0" y2="1"><stop stop-color="#914cff" stop-opacity=".35"/><stop offset="1" stop-color="#914cff" stop-opacity="0"/></linearGradient></defs>${[0,1,2,3].map(i=>`<path d="M50 ${180-i*48}H620" class="chart-grid"/><text x="2" y="${184-i*48}">${hours(max*i/3)}</text>`).join('')}<polygon points="50,180 ${line} 620,180" fill="url(#chart-fill)"/><polyline points="${line}" fill="none" stroke="#a76bff" stroke-width="3"/>${pts.map(([x,y],i)=>`<circle cx="${x}" cy="${y}" r="4" fill="#b987ff"><title>${esc(entries[i].label)}: ${hours(entries[i].n)}</title></circle><text x="${x}" y="210" text-anchor="middle">${esc(entries[i].label)}</text>`).join('')}</svg>`;}
function dashboardRanking(){const rows=state.social?.rows?.slice(0,5)||[];return `<div class="card dashboard-ranking">${section('Ranking de editores','',goto('Ver ranking','friends'))}${rows.length?rows.map(r=>`<div class="ranking-mini ${r.mine?'mine':''}"><span>${fmt(r.position)}</span><strong>${esc(r.nickname)}</strong><span>${hours(r.seconds)}</span></div>`).join(''):`<div class="ranking-placeholder">${icon('achievements')}<h3>Tu lugar entre editores</h3><p>Conecta tu cuenta para ver la clasificación y tus rivales.</p>${goto('Abrir Social','friends')}</div>`}</div>`;}
function overview(){return `<div class="dashboard"><div class="dashboard-top"><section class="card session-panel"><h2>${icon('render')} Tiempo de edición activo</h2><div class="session-content"><div><div class="timer" id="live-timer">${clock(state.session?.seconds)}</div><p>Sesión de edición actual</p><div class="session-status"><i class="status-dot ${state.active?'on':''}" id="status-dot"></i><span id="live-status">${esc(state.reason)}</span></div></div>${editorTimeline()}</div><div class="session-bottom"><span id="live-project">${esc(state.bridge.name||'Premiere Pro')}</span><span id="live-session-xp">+${fmt(state.session?.xp)} XP</span>${goto('Modo enfoque','focus')}</div></section>${studioProfile()}</div><div class="dashboard-middle"><section class="card dashboard-level"><div class="level-rank">${rankImg()}<div><h2>Nivel ${state.level.level}</h2><span>${esc(state.rank.name)}</span></div></div><div class="xp-track"><div class="row"><span>Progreso de nivel (XP)</span><span>${fmt(state.level.into)} / ${fmt(state.level.need)} XP</span></div><div class="xp-ruler"></div>${progress(state.level.into,state.level.need)}<div class="row small muted"><span>0</span><span>${fmt(state.level.need)} XP</span></div></div></section></div>${studioMetrics()}<div class="dashboard-bottom"><section class="card activity-panel">${section('Actividad semanal','Tiempo de edición por día',goto('Ver estadísticas','stats'))}${activityGraph()}</section>${dashboardRanking()}</div><div class="grid two dashboard-extra"><div class="card">${section('Un reto para hoy','',goto('Ver retos','quests'))}${quest(state.daily)}${quest(state.week[0])}</div><div class="card">${section('Actividad reciente')}${activity(3)}</div></div></div>`;}
function ranks(){const list=state.ranks||[];return `<div class="card rank-journey-summary"><div><span class="eyebrow">TU PROGRESO</span><h2>${esc(state.rank.name)}</h2><p>${fmt(state.xp)} XP acumulados</p></div>${rankImg()}<div>${state.nextRank?`<strong>${fmt(state.nextRank.xp-state.xp)} XP para ${esc(state.nextRank.name)}</strong>${progress(state.xp-state.rank.xp,state.nextRank.xp-state.rank.xp)}`:'<strong>Alcanzaste el rango máximo</strong>'}</div></div><ol class="rank-journey">${list.map((r,i)=>{const reached=state.xp>=r.xp,current=state.rank.name===r.name;return `<li class="${reached?'reached':''} ${current?'current':''}" ${current?'aria-current="step"':''}><div class="rank-stop">${rankImg(r.name,'')}</div><div class="card rank-step"><div><span class="eyebrow">RANGO ${i+1} · ${current?'ACTUAL':reached?'ALCANZADO':'POR DESBLOQUEAR'}</span><h2>${esc(r.name)}</h2><p>${fmt(r.xp)} XP totales necesarios</p><span class="muted small">${reached?'Ya alcanzaste este rango':`Te faltan ${fmt(r.xp-state.xp)} XP`}</span></div><div class="rank-unlocks"><span class="tag">Banner ${esc(r.name)}</span><p class="earned-title" style="--title-color:${r.color}">${esc(state.titles?.find(t=>t.id==='rank_'+r.name.toLowerCase())?.name||'')}</p></div></div></li>`;}).join('')}</ol>`;}
function patchArticle(p){return `<article class="patch-article"><div class="patch-version">VERSIÓN ${esc(p.version)} · ${esc(p.date)}</div><h2>${esc(p.title)}</h2>${p.sections.map(s=>`<section><h3>${esc(s.title)}</h3><ul>${s.items.map(text=>`<li>${esc(text)}</li>`).join('')}</ul></section>`).join('')}</article>`;}
function updates(){const notes=state.releases?.notes||[];return `<div class="note">Tu buzón de actualizaciones · cambios, correcciones y ajustes de balance. Versión instalada: ${esc(state.version)}.</div><div class="patch-history">${notes.map((p,i)=>`<details class="card" ${i===0?'open':''}><summary>Versión ${esc(p.version)} · ${esc(p.title)}</summary>${patchArticle(p)}</details>`).join('')||empty('Sin notas disponibles','Las novedades aparecerán aquí con la próxima actualización.')}</div>`;}
function showReleaseNotes(){if(document.hidden||$('#modal').open||!state?.releases?.unread)return;const patch=state.releases.notes.find(p=>p.version===state.version);if(!patch)return;$('#modal').dataset.releaseVersion=state.version;modal(`<div class="eyebrow">NOVEDADES DE RANKED PRO</div>${patchArticle(patch)}<p class="muted small">Puedes volver a leer este parche desde Novedades en el menú izquierdo.</p>`);}
function focus(){return `<div class="card focus-view">${rankImg()}<span class="eyebrow" style="margin-top:15px">TU TIEMPO. TU PROGRESO.</span><div class="timer" id="live-timer">${clock(state.session?.seconds)}</div><span id="live-status" class="pill ${state.active?'good':''}">${esc(state.reason)}</span><div class="timer-sub" id="live-project">${esc(state.bridge.name||'Abre Premiere y trabaja a tu ritmo.')}</div>${progress(state.daySeconds,state.settings.dailyMinutes*60,true)}<span class="muted small">${hours(state.daySeconds)} / ${state.settings.dailyMinutes} minutos de meta diaria</span><div class="row" style="margin-top:32px">${btn(state.paused?'Reanudar':'Pausar','pause','','primary')}${btn('Terminar sesión','endSession')}${btn('Enviar a bandeja','hide')}</div><p class="muted small" style="margin-top:25px">Cambia a Premiere. El contador se pausa cuando trabajas en otra aplicación.</p></div>`;}
function stats(){const s=state.stats;return `${metrics()}${section('Los últimos 14 días','Tu tiempo activo, día a día',btn('Exportar proyectos CSV','csv'))}<div class="card">${chart(14)}</div>${section('Dentro de Premiere','Los eventos dependen del puente; los cortes se estiman por cambios de clips.')}<div class="grid four">${[['Ediciones estimadas',s.edits],['Ajustes de clips',s.trims],['Efectos añadidos',s.fx],['Exportaciones',s.renders]].map(([n,v])=>`<div class="card"><span class="metric-label">${n}</span><div class="metric-number">${fmt(v)}</div></div>`).join('')}</div>${section('Sesiones recientes','Una sesión termina después de 15 minutos sin actividad.') }<div class="card">${state.sessions.length?`<table class="table"><thead><tr><th>FECHA</th><th>TIEMPO ACTIVO</th><th>XP DE TIEMPO</th><th>ESTIMACIÓN</th></tr></thead><tbody>${state.sessions.slice(0,40).map(s=>`<tr><td>${date(s.start)} · ${new Date(s.start).toLocaleTimeString('es-MX',{hour:'2-digit',minute:'2-digit'})}</td><td>${clock(s.seconds)}</td><td>+${fmt(s.xp)} XP</td><td>${money(s.money)}</td></tr>`).join('')}</tbody></table>`:empty('Aún no hay sesiones terminadas','Tu sesión actual se guarda automáticamente. Puedes finalizarla desde Modo enfoque.')}</div>${section('Resumen mensual','Una vista lista para guardar como imagen.',btn('Guardar resumen PNG','recap'))}<div class="card" id="recap-card"><div class="row"><div><span class="eyebrow">RANKED PRO · ${new Date().toLocaleDateString('es-MX',{month:'long',year:'numeric'}).toUpperCase()}</span><h2 style="font-size:26px;margin-top:10px">${esc(state.name)}</h2><p class="muted">Mi mes, corte a corte.</p></div>${rankImg()}</div><div class="grid three">${[['Horas del mes',hours(Object.entries(state.dayLog).filter(([k])=>k.startsWith(new Date().getFullYear()+'-'+String(new Date().getMonth()+1).padStart(2,'0'))).reduce((s,[,v])=>s+v,0))],['Rango actual',state.rank.name],['Racha récord',state.bestStreak+' días']].map(([k,v])=>`<div><span class="metric-label">${k}</span><div class="metric-number">${v}</div></div>`).join('')}</div></div>`;}
function quests(){return `<div class="note">10 XP por minuto activo. Bonos diarios: 15 min +50 XP · 30 min +100 · 60 min +150 · 120 min +200. Se acumulan entre sesiones. Doble XP solo multiplica el tiempo activo; los bonos se entregan una vez.</div><div class="grid two"><div class="card">${section('Tu meta diaria',`${state.settings.dailyMinutes} minutos elegidos por ti`)}<div class="metric-number">${hours(state.daySeconds)}</div>${progress(state.daySeconds,state.settings.dailyMinutes*60,true)}<p class="muted small">Cuenta solo mientras Premiere está en foco y sigues activo.</p>${goto('Cambiar meta','settings')}</div><div class="card">${section('Tu meta semanal',`${state.settings.weeklyHours} horas para esta semana`)}<div class="metric-number">${hours(state.weekSeconds)}</div>${progress(state.weekSeconds,state.settings.weeklyHours*3600,true)}<p class="muted small">La constancia importa más que una sesión interminable.</p></div></div>${section('Misión del día','Se renueva cada día.')}<div class="card">${quest(state.daily)}</div>${section('Tus cinco retos semanales','Las recompensas se entregan automáticamente.')}<div class="card">${state.week.map(quest).join('')}</div>${section('Cofre de la semana')}<div class="card chest"><div class="chest-symbol">▣</div><div class="info"><h2>${state.chestOpened?'Cofre reclamado':state.chestReady?'Tu cofre está listo':'Una recompensa por aparecer'}</h2><p>30 minutos de edición esta semana desbloquean un cofre. Contiene fichas para la tienda local.</p></div><button class="button primary" data-action="chest" ${!state.chestReady?'disabled':''}>${state.chestOpened?'Abierto':'Abrir cofre'}</button></div>`;}
const prestigeLevels=[
 {max:150,name:'Normal',color:'#a5afbf'},
 {max:400,name:'Poco común',color:'#75ce97'},
 {max:1000,name:'Rara',color:'#76b8ff'},
 {max:1500,name:'Súper rara',color:'#e5de72'},
 {max:2999,name:'Épica',color:'#ff807b'},
 {max:Infinity,name:'Legendaria',color:'#f5ba49'}
];
const prestige=badge=>prestigeLevels.find(level=>badge.reward<=level.max)||prestigeLevels[0];
function badgeSymbol(badge){
 const id=badge.id||'';
 let drawing='';
 if(/^(saver|perfectionist)$/.test(id))drawing='<path d="M5 3h12l4 4v14H3V3z M7 3v7h10V3 M7 21v-7h10v7"/>';
 else if(/^streak_/.test(id))drawing='<path d="M13 2c2 6-3 7-1 11 2-1 3-3 3-5 4 4 5 6 4 9a7 7 0 0 1-14 0c-1-4 2-7 4-9 0 3 1 4 2 4-1-4 2-6 2-10Z"/>';
 else if(/^(first_render|render_10|render_100)$/.test(id))drawing='<path d="M3 8V3h13 M6 11V6h13 M3 12h13v9H3z M19 12l3 3-3 3 M17 15h5"/><path d="m8 15 4 2-4 2z"/>';
 else if(/^(first_steps|warm_up|serious|dedicated|centurion|quarter|thousand|in_the_zone|marathon)$/.test(id))drawing='<circle cx="12" cy="9" r="6"/><path d="M12 5v4l3 2 M2 21h20 M4 19v4 M12 19v4 M20 19v4"/>';
 else if(/^(cutter|butcher|editor_10k)$/.test(id))drawing='<circle cx="5" cy="6" r="3"/><circle cx="5" cy="18" r="3"/><path d="m7 8 14 13 M7 16 21 3"/>';
 else if(/^(night_owl|insomnia|dawn)$/.test(id))drawing='<path d="M19 16A9 9 0 0 1 8 3a9 9 0 1 0 11 13Z"/><path d="M17 3v4 M15 5h4"/>';
 else if(/^(fx_fiend|fx_wizard|fx_collector)$/.test(id))drawing='<path d="m12 2 3 7 7 3-7 3-3 7-3-7-7-3 7-3Z M20 2v4 M18 4h4"/>';
 if(id==='first_steps')drawing='<path d="m9 3 9 5-9 5z M2 20h20 M4 18v4 M12 18v4 M20 18v4"/>';
 if(id==='thousand')drawing='<circle cx="12" cy="9" r="5"/><path d="M12 6v3l2 1 M4 7C0 14 4 20 9 21 M20 7c4 7 0 13-5 14 M2 11l3 2 M2 16l4 1 M22 11l-3 2 M22 16l-4 1"/>';
 if(!drawing){
  const shapes={
   tenure:'M4 5h16v16H4z M4 10h16 M8 2v6 M16 2v6 M8 14h2 M14 14h2 M8 18h2 M14 18h2',
   streak:'M4 5h16v16H4z M8 2v6 M16 2v6 M7 15l3 3 7-7',
   time:'M12 3a9 9 0 1 0 0 18 9 9 0 0 0 0-18 M12 7v5l4 2',
   edit:'M3 5h18v4H3z M3 12h12v4H3z M8 19h13v3H8z M17 2v17',
   render:'M3 4h14v17H3z M6 8h5 M6 12h4 M13 15h9 M19 12l3 3-3 3',
   social:'M8 3a3 3 0 1 0 0 6 3 3 0 0 0 0-6 M2 21v-4a6 6 0 0 1 12 0v4 M17 3a3 3 0 0 1 0 6 M18 13a5 5 0 0 1 4 5v3'
  };
  const shape=/^account_age_/.test(id)?shapes.tenure:shapes[badge.category]||'M7 3h10v6a5 5 0 0 1-10 0z M7 5H3v3a4 4 0 0 0 4 4 M17 5h4v3a4 4 0 0 1-4 4 M12 14v6 M7 21h10';
  drawing=`<path d="${shape}"/>`;
 }
 return `<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.7" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">${drawing}</svg>`;
}
function badgeIcon(badge){
 const level=prestige(badge);
 const detail=[badge.name,level.name,badge.description].filter(Boolean).join(' · ');
 return `<span class="badge-medal ${level===prestigeLevels.at(-1)?'legendary':''}" style="--metal:${level.color}" tabindex="0" role="img" aria-label="${esc(detail)}" data-badge-detail="${esc(detail)}">${badgeSymbol(badge)}</span>`;
}
function achievements(){const list=state.achievements.filter(a=>(filter==='all'||filter==='unlocked'&&a.unlocked||filter==='available'&&!a.pending||filter===a.category)&&(!search||(a.name+' '+a.description).toLowerCase().includes(search.toLowerCase())));return `<div class="row"><div><span class="metric-number">${state.achievements.filter(a=>a.unlocked).length}<span class="muted" style="font-size:16px"> / ${state.achievements.length}</span></span><p class="muted small">Logros desbloqueados · selecciona uno obtenido para mostrarlo en tu perfil.</p></div><input id="achievement-search" placeholder="Buscar un logro…" value="${esc(search)}" aria-label="Buscar logro"></div><div class="toolbar">${[['all','Todos'],['available','Disponibles localmente'],['unlocked','Desbloqueados'],['time','Tiempo'],['tenure','Antigüedad'],['streak','Constancia'],['edit','Edición'],['render','Exportación'],['social','Sociales']].map(([id,n])=>`<button class="button quiet ${filter===id?'active':''}" data-filter="${id}">${n}</button>`).join('')}</div><div class="grid three">${list.map(a=>`<div class="card achievement ${a.unlocked?'':'locked'} ${a.pending?'pending':''}">${badgeIcon(a)}<div class="info"><div class="row"><h3>${esc(a.name)}</h3>${a.unlocked?'<span class="check">✓</span>':''}</div><span class="prestige-label" style="--metal:${prestige(a).color}">${prestige(a).name}</span><p>${esc(a.description)}</p>${progress(a.progress,a.goal,a.unlocked)}<div class="row" style="margin-top:8px"><span class="metric-foot">${a.pending?esc(a.pending):fmt(a.progress)+' / '+fmt(a.goal)}</span><span class="xp">+${a.reward}</span></div>${a.unlocked?btn(state.cosmetics.badges.includes(a.id)?'Quitar insignia':'Mostrar insignia','badge',a.id,'quiet'):''}</div></div>`).join('')}</div>${!list.length?empty('Sin coincidencias','Prueba con otro filtro o término.'):''}`;}
function projects(){return `<div class="note">Las tarifas son estimaciones personales en ${state.settings.currency}. No se envían a ningún servidor. El tiempo sin puente se conserva en tu total, pero no se asigna a un proyecto.</div>${section('Tus proyectos',state.projects.length+' proyectos con tiempo registrado',btn('Exportar CSV','csv'))}<div class="card">${state.projects.length?`<table class="table"><thead><tr><th>PROYECTO</th><th>TIEMPO ACTIVO</th><th>ESTIMACIÓN</th><th></th></tr></thead><tbody>${state.projects.map(p=>`<tr><td><h3>${esc(p.name||p.key.split(/[\\/]/).pop())}</h3><div class="project-path">${esc(p.key)}</div></td><td>${clock(p.seconds)}</td><td>${money(p.money)}<div class="muted small">${money(p.rate??state.settings.hourlyRate)}/h</div></td><td>${btn('Notas y tarifa','editProject',p.key,'quiet')}</td></tr>`).join('')}</tbody></table>`:empty('Tu próximo proyecto empieza aquí','Carga Ranked Pro Bridge desde Premiere. Cuando edites, el proyecto y sus horas aparecerán automáticamente.')}</div>`;}
function shop(){let list=state.shop.filter(i=>(shopFilter==='all'||shopFilter==='owned'&&i.owned||shopFilter===i.kind));return `<div class="card row"><div><span class="eyebrow">TU CARTERA LOCAL</span><div class="metric-number">◈ ${fmt(state.balance)} <span class="muted small">fichas</span></div></div><span class="muted small">1 ficha por cada 10 XP + bonos por metas, retos, logros y rangos.<br>30 min activos: +15 fichas · reto diario: +10 · semanal: +25.</span>${btn('Restablecer apariencia','equip','default','quiet')}</div><div class="toolbar">${[['all','Todo'],['owned','Mi inventario'],['banner','Banners'],['namefx','Efectos de nombre'],['deco','Decoraciones']].map(([id,n])=>`<button class="button quiet ${shopFilter===id?'active':''}" data-shop-filter="${id}">${n}</button>`).join('')}</div><div class="grid three">${list.map(i=>`<div class="card shop-card"><div class="shop-preview" ${i.kind==='banner'?`style="background-image:url('${bannerUrl(i.id)}')"`:''}>${i.kind==='namefx'?`<span class="name-preview animated-name" style="${nameStyle(i.id)}">${esc(state.name)}</span>`:i.kind==='deco'?`<img src="../assets/img/fx/decos-${i.id}.png" alt="">`:''}</div><span class="shop-kind">${({banner:'Banner',namefx:'Efecto de nombre',deco:'Decoración'})[i.kind]}</span><h3>${esc(i.name)}</h3><div class="condition">${esc(i.condition||'Desbloquea con tus fichas de edición.')}</div><div class="row"><span class="xp">${i.owned?'En tu inventario':'◈ '+i.price}</span>${i.owned?btn(i.equipped?'Equipado ✓':'Equipar','equip',i.key,'purple'):`<button class="button quiet" data-action="buy" data-value="${i.key}" ${i.condition||state.balance<i.price?'disabled':''}>Desbloquear</button>`}</div></div>`).join('')}</div>${!list.length?empty('Tu colección está por comenzar','Edita, gana XP y consigue tus primeras fichas.'):''}`;}
function badgeRow(ids){
 if(!ids.length)return '';
 const icons=ids.map(id=>state.achievements.find(item=>item.id===id)||{id,name:id})
  .sort((a,b)=>(b.reward||0)-(a.reward||0)).map(badgeIcon);
 const extra=icons.length-6;
 return `<div class="profile-badges"><div class="badges">${icons.slice(0,6).join('')}${extra>0?`<button type="button" class="button quiet" data-action="extraBadges" aria-label="Mostrar ${extra} insignias más" aria-expanded="false">+${extra}</button>`:''}</div>${extra>0?`<div class="badges extra-badges" hidden>${icons.slice(6).join('')}</div>`:''}</div>`;
}
function speedControl(){
 const speed=state.settings.nameSpeed||1;
 return `<label>Velocidad del nombre<select name="nameSpeed">${[0.25,0.5,1,1.5,2,3,4].map(v=>`<option value="${v}" ${v===speed?'selected':''}>${v}×</option>`).join('')}</select></label>`;
}
function setSpeed(element,speed){
 element.style.setProperty('--name-duration',(1.15/(Number(speed)||1))+'s');
}
function profileSummary(){return `<div class="card studio-profile"><div class="profile-cover" style="background-image:url('${esc(state.bannerGif||(state.cosmetics.banner?bannerUrl(state.cosmetics.banner):'studio-timeline.svg'))}')"></div>${state.avatar?`<img class="avatar" src="${esc(state.avatar)}" alt="Foto de perfil">`:icon('profile')}<div><span class="eyebrow">TU PERFIL</span><h2 class="${state.cosmetics.namefx?'animated-name':''}" style="${nameStyle(state.cosmetics.namefx)}">${esc(state.name)}</h2>${titleLabel()}<span class="muted small">${esc(state.rank.name)} · Nivel ${state.level.level}</span></div>${goto('Personalizar perfil','profile')}</div><div class="card level-timeline"><div class="row"><span>Progreso de nivel · ${state.level.level}</span><span>${fmt(state.level.into)} / ${fmt(state.level.need)} XP</span></div>${progress(state.level.into,state.level.need)}</div>`;}
function bannerUrl(id){return '../assets/img/fx/banner-'+encodeURIComponent(id)+(id.startsWith('rank_')?'.svg':'.png');}
function titleLabel(){const title=state.titles?.find(t=>t.equipped);return title?`<div class="earned-title" style="--title-color:${title.color}">${esc(title.name)}</div>`:'';}
function titleChoices(){return `${section('Títulos de editor','Se desbloquean con tus rangos y logros. Puedes equipar uno debajo de tu nombre.',btn('Sin título','equip','title:','quiet'))}<div class="title-grid">${(state.titles||[]).map(t=>`<div class="title-choice ${t.unlocked?'':'locked'}"><div class="earned-title" style="--title-color:${t.color}">${esc(t.name)}</div><p class="muted small">${esc(t.condition)}</p><button class="button quiet" data-action="equip" data-value="title:${t.equipped?'':esc(t.id)}" ${t.unlocked?'':'disabled'}>${t.equipped?'Quitar título':t.unlocked?'Equipar':'Bloqueado'}</button></div>`).join('')}</div>`;}
function profile(){return `<div class="grid two"><div class="card profile-card" id="profile-card"><div class="profile-cover" style="background-image:url('${esc(state.bannerGif|| (state.cosmetics.banner?bannerUrl(state.cosmetics.banner):'studio-timeline.svg'))}')"></div><span class="eyebrow">RANKED PRO · PERFIL LOCAL</span><div class="portrait">${state.avatar?`<img class="profile-photo" src="${esc(state.avatar)}" alt="Foto de perfil">`:rankImg()}${state.cosmetics.deco?`<img class="profile-deco" src="../assets/img/fx/decos-${esc(state.cosmetics.deco)}.png" alt="Decoración">`:""}</div><h2 class="${state.cosmetics.namefx?'animated-name':''}" style="${nameStyle(state.cosmetics.namefx)}">${esc(state.name)}</h2>${titleLabel()}${badgeRow(state.cosmetics.badges)}<span class="muted">${esc(state.title||'Una historia en cada corte.')}</span><div class="rank-name" style="margin-top:22px;color:${state.rank.color}">${state.rank.name}</div><span class="muted small">Nivel ${state.level.level} · ${fmt(state.xp)} XP · ${hours(state.seconds)}</span><p class="metric-foot">Miembro desde ${date(state.created)}</p></div><div class="stack"><div class="card">${section('Hazlo tuyo')}<form id="profile-form" class="stack"><label>Nombre de editor<input name="name" maxlength="40" required value="${esc(state.name)}"></label><label>Tu frase<input name="title" maxlength="80" value="${esc(state.title)}" placeholder="Una historia en cada corte."></label>${speedControl()}<button class="button primary" type="submit">Guardar perfil</button></form><div class="row" style="margin-top:20px">${btn('Elegir foto','avatar')}${btn('GIF de banner · Radiante','bannerGif','','quiet')}${goto('Personalizar','shop')}${btn('Guardar tarjeta PNG','card')}</div></div><div class="card">${section('Tu siguiente nivel')}<div class="row"><span>Nivel ${state.level.level}</span><span class="muted small">${fmt(state.level.into)} / ${fmt(state.level.need)} XP</span></div><div style="margin-top:14px">${progress(state.level.into,state.level.need)}</div><p class="muted small">Diamante desbloquea GIF para tu foto; Radiante desbloquea GIF para el banner. Máximo 5 MB por GIF.</p></div></div></div>${titleChoices()}${section('Mi inventario')}${btn('Quitar banner','equip','banner:','quiet')}${btn('Restablecer apariencia','equip','default','quiet')}${cosmeticChoices()}${section('El camino de rangos')}<div class="card rank-list">${['IRON','BRONZE','SILVER','GOLD','PLATINUM','DIAMOND','ASCENDANT','IMMORTAL','RADIANT'].map(n=>`<div class="rank-item ${state.rank.name===n?'current':''}">${rankImg(n,'')}<div>${n}</div></div>`).join('')}</div>`;}
function cosmeticChoices(trial=false){
 return [['namefx','Efectos de nombre'],['deco','Decoraciones'],['banner','Banners'],['badge','Insignias']].map(([kind,label])=>{
  const items=kind==='badge'?state.achievements.filter(a=>trial||a.unlocked):state.shop.filter(a=>a.kind===kind&&(trial||a.owned));
  const cards=items.map(item=>{
   const selected=kind==='badge'?state.cosmetics.badges.includes(item.id):state.cosmetics[kind]===item.id;
   const visual=kind==='badge'?badgeIcon(item):kind==='namefx'?`<span class="animated-name" style="${nameStyle(item.id)}">${esc(state.name)}</span>`:`<img src="${kind==='banner'?bannerUrl(item.id):'../assets/img/fx/decos-'+encodeURIComponent(item.id)+'.png'}" alt="">`;
   return trial?`<label class="cosmetic-choice"><input type="${kind==='badge'?'checkbox':'radio'}" name="${kind}" value="${esc(item.id)}"><span class="choice-art">${visual}</span><span>${esc(item.name)}</span></label>`:`<button type="button" class="cosmetic-choice" aria-pressed="${selected}" data-action="${kind==='badge'?'badge':'equip'}" data-value="${esc(kind==='badge'?item.id:item.key)}"><span class="choice-art">${visual}</span><span>${esc(item.name)}${selected?' ?':''}</span></button>`;
  }).join('');
  return `<details class="cosmetic-section" open><summary>${label} ? ${items.length}</summary><div class="cosmetic-grid">${trial&&kind!=='badge'?`<label class="cosmetic-choice"><input type="radio" name="${kind}" value="" checked><span>Sin efecto</span></label>`:''}${cards||'<p class="muted">A?n no tienes recompensas de este tipo.</p>'}</div></details>`;
 }).join('');
}
function admin(){
 const controls=cosmeticChoices(true);
 return `<div class="grid two"><div class="card profile-card" id="admin-preview"><div class="profile-cover" id="trial-cover"></div><div id="trial-portrait" class="portrait">${state.avatar?`<img class="profile-photo" alt="" src="${esc(state.avatar)}">`:rankImg()}</div><h2 id="trial-name">${esc(state.name)}</h2><div id="trial-badge"></div></div><form class="card stack" id="trial-controls"><h2>Probar en mi tarjeta</h2><p class="muted small">Combina recompensas, incluso las bloqueadas. Las pruebas son temporales.</p>${controls}${speedControl()}<label>Foto de prueba<input type="file" name="photo" accept="image/png,image/jpeg,image/gif"></label><label>GIF de banner de prueba<input type="file" name="backdrop" accept="image/gif"></label><button type="reset" class="button quiet">Restablecer prueba</button></form></div>`;
}
function bindTrial(){
 const form=$('#trial-controls');
 if(!form)return;
 const portrait=$('#trial-portrait'), original=portrait.innerHTML;
 const files={};
 function draw(){
  const values=new FormData(form), name=$('#trial-name');
  name.classList.toggle('animated-name',Boolean(values.get('namefx')));
  name.style.cssText=nameStyle(values.get('namefx'));
  const deco=values.get('deco'), banner=values.get('banner');
  portrait.innerHTML=(files.photo?`<img class="profile-photo" src="${files.photo}" alt="">`:original)+(deco?`<img class="profile-deco" src="../assets/img/fx/decos-${esc(deco)}.png" alt="">`:'');
  $('#trial-badge').innerHTML=badgeRow(values.getAll('badge'));
  setSpeed($('#admin-preview'),values.get('nameSpeed'));
  const background=banner?bannerUrl(banner):files.backdrop;
  $('#trial-cover').style.backgroundImage=background?`url("${background}")`:'';
 }
 const pending={};
 form.onchange=async ({target})=>{
  if(target.type==='file'){
   const file=target.files[0], key=target.name;
   const reader=new FileReader();
   pending[key]=reader;
   delete files[key];
   if(file){
    if(file.size>5*1024*1024){target.value='';toast('El máximo por imagen de prueba es 5 MB.');draw();return;}
    reader.onload=()=>{if(pending[key]===reader){files[key]=reader.result;if(key==='backdrop')form.querySelector('input[name="banner"][value=""]').checked=true;draw();}};
    reader.readAsDataURL(file);
   }
  }
  draw();
 };
 form.onreset=()=>{for(const key of ['photo','backdrop']){delete pending[key];delete files[key];}queueMicrotask(draw);};
}
function journal(){return `<div class="note">Tu diario es privado y local. Las publicaciones compartidas, mensajes y duelos estarán disponibles cuando incorporemos cuentas y servidor.</div><form id="post-form" class="card"><h2>¿Qué creaste hoy?</h2><p class="muted small">Anota una idea, una lección o el siguiente paso de tu edición.</p><textarea name="text" maxlength="5000" required placeholder="Hoy encontré el ritmo de esta secuencia…"></textarea><div class="row" style="margin-top:14px"><span class="muted small">Solo en este equipo</span><button type="submit" class="button primary">Guardar en mi diario</button></div></form>${gallery()}${section('Tu bitácora',state.posts.length+' entradas')}<div class="stack">${state.posts.length?state.posts.map(p=>`<div class="card"><div class="row"><span class="muted small">${date(p.at)} · ${esc(state.name)}</span>${btn('Eliminar','deletePost',p.id,'quiet danger')}</div><div class="post">${esc(p.text)}</div></div>`).join(''):empty('No dejes escapar tus ideas','Tu primera entrada puede ser una meta para tu próxima sesión.')}</div>`;}
function rankingIdentity(row){
 const a=row.appearance||{};
 const avatar=typeof a.avatar==='string'&&/^data:image\/png;base64,[A-Za-z0-9+/=]+$/.test(a.avatar)?`<img class="ranking-avatar" src="${a.avatar}" alt="">`:'';
 const effect=state.shop.some(item=>item.kind==='namefx'&&item.id===a.namefx)?a.namefx:'';
 const badges=(Array.isArray(a.badges)?a.badges:[]).filter(id=>state.achievements.some(item=>item.id===id));
 return `<div class="ranking-identity">${avatar}<div><span class="${effect?'animated-name':''}" style="${nameStyle(effect)};--name-duration:${1.15/(Number(a.speed)||1)}s">${esc(row.nickname)}</span>${badgeRow(badges)}</div></div>`;
}
function friends(){
 const social=state.social||{};
 if(!social.ready)return '<div class="card"><h2>Ranking de editores</h2><p>El registro estará disponible cuando se conecte el servidor de Ranked Pro.</p></div>';
 if(!social.logged)return `<div class="grid two">${[['login','Iniciar sesión'],['signup','Crear cuenta']].map(([kind,title])=>`<form class="card stack" data-auth="${kind}"><h2>${title}</h2>${kind==='signup'?'<label>Nombre público<input required minlength="2" maxlength="32" name="nickname"></label><p class="muted small">Tu nombre y tus horas de edición aparecerán en la clasificación pública. El contador comienza al iniciar sesión.</p>':''}<label>Correo<input type="email" required name="email" autocomplete="email"></label><label>Contraseña<input type="password" required name="password" autocomplete="${kind==='signup'?'new-password':'current-password'}" ${kind==='signup'?'minlength="8"':''}></label><button class="button primary">${title}</button>${kind==='login'?'<button type="submit" value="resend" formnovalidate class="button quiet">Reenviar confirmación</button>':''}</form>`).join('')}</div>`;
 return `<div class="card"><div class="row"><h2>${esc(social.name)}</h2><div>${btn('Actualizar','sync')} ${btn('Cerrar sesi?n','logout','','quiet')}</div></div><p class="muted">Tiempo de edici?n acumulado con la sesi?n social iniciada.</p>${social.error?`<p role="status">${esc(social.error)}</p>`:''}<div class="social-table"><table class="table"><thead><tr><th>Puesto</th><th>Editor</th><th>Tiempo</th><th>Rivales</th></tr></thead><tbody>${social.rows.map(r=>`<tr><td>${fmt(r.position)}</td><td>${rankingIdentity(r)}${r.mine?' ? T?':''}</td><td>${clock(r.seconds)}</td><td>${r.id&&!r.mine?btn(r.following?'Dejar de seguir':'Seguir','followEditor',r.id,'quiet')+' '+btn('Mensaje','messageEditor',r.id,'quiet'):''}</td></tr>`).join('')}</tbody></table></div></div>${social.upgraded?`<section class="card" style="margin-top:20px"><h2>Mensajes privados</h2><p class="muted">${social.inbox.following} rivales ? ${social.inbox.followers} seguidores ? ${social.inbox.messagesSent} mensajes enviados</p>${social.inbox.messages.map(m=>`<div class="activity"><div><strong>${esc(m.mine?'T? ? '+m.recipient_name:m.sender_name+' ? T?')}</strong><p>${esc(m.body)}</p></div>${btn('Responder','messageEditor',m.mine?m.recipient:m.sender,'quiet')}</div>`).join('')||'<p class="muted">Selecciona Mensaje junto a un editor para iniciar una conversaci?n.</p>'}</section>`:'<p class="note">Las nuevas funciones sociales estar?n disponibles al actualizar el servidor.</p>'}`;

}

function settings(){const s=state.settings;return `<form id="settings-form"><div class="grid two"><div class="card">${section('Seguimiento','Premiere en foco + actividad reciente.')}<div class="form-grid"><label>Pausar tras inactividad (segundos)<input name="idleSeconds" type="number" min="5" max="600" value="${s.idleSeconds}"></label><label>Meta diaria (minutos)<input name="dailyMinutes" type="number" min="0" max="1440" value="${s.dailyMinutes}"></label><label>Meta semanal (horas)<input name="weeklyHours" type="number" min="0" max="168" value="${s.weeklyHours}"></label><label>Tarifa por hora<input name="hourlyRate" type="number" min="0" max="100000" step="0.01" value="${s.hourlyRate}"></label><label>Moneda<select name="currency">${['MXN','USD','EUR','GBP','CAD','BRL','COP','ARS','CLP','PEN','JPY'].map(c=>`<option ${s.currency===c?'selected':''}>${c}</option>`).join('')}</select></label><label>Apariencia<select name="theme"><option value="dark" ${s.theme==='dark'?'selected':''}>Oscura</option><option value="light" ${s.theme==='light'?'selected':''}>Clara</option></select></label></div></div><div class="card">${section('Ventana y bandeja')} ${[['tray','Seguir al cerrar la ventana','La X oculta la ventana; Salir termina el seguimiento.'],['startup','Iniciar con Windows','Se abre directamente en la bandeja del sistema.'],['notifications','Notificar hitos','Logros, nuevos rangos y metas completadas.'],['sound','Sonido de notificación','Utiliza el sonido de las notificaciones de Windows.']].map(([id,title,desc])=>`<div class="setting-row"><label for="${id}">${title}<small>${desc}</small></label><input type="checkbox" id="${id}" name="${id}" ${s[id]?'checked':''}></div>`).join('')}</div></div><div class="row" style="margin:18px 0 30px"><span class="muted small">La reproducción sin actividad también se pausa al vencer el tiempo de inactividad.</span><button type="submit" class="button primary">Guardar ajustes</button></div></form><div class="grid two"><div class="card">${section('Puente con Premiere',state.connected?'Conectado':'Pendiente de conexión')}<ol class="help-list"><li>Instala el puente con el botón de abajo.</li><li>Guarda tu trabajo y reinicia Premiere.</li><li>Abre Ventana → Complementos UXP → Ranked Pro Bridge.</li><li>Déjalo cargado detrás de otro panel. Cierra el panel VISFX anterior para evitar su consumo.</li></ol><p class="muted small">El puente no modifica proyectos. Si se descarga, el tiempo sigue funcionando, pero no los datos de edición.</p>${btn('Instalar / reparar puente','installBridge','','purple')}<details style="margin-top:20px"><summary class="muted small">Diagnóstico</summary><p class="project-path">${esc(state.bridge.error||'Sin errores comunicados por el puente.')}<br>${esc(state.bridge.capabilities.join(', ')||'Sin eventos conectados todavía.')}</p></details></div><div class="card">${section('Tus datos, bajo tu control')}<p class="muted small">Respaldo JSON del perfil, proyectos y progreso. Copia también la carpeta media para conservar los archivos de tu galería. No se importa la cuenta de VISFX ni se conecta con su clasificación.</p><div class="toolbar">${btn('Exportar respaldo','export')}${btn('Restaurar respaldo','import')}${btn('Abrir carpeta de datos','openData','','quiet')}</div><p class="project-path">${esc(state.storage)}</p><hr style="border:0;border-top:1px solid var(--border);margin:22px 0"><h3>Ranked Pro ${esc(state.version)}</h3><p class="muted small">Edición local para Windows. Los cambios netos de clips son estimaciones, no un registro exacto de cada corte. Los logros sin detección o funciones sociales están indicados como pendientes.</p>${btn('Salir de Ranked Pro','quit','','quiet danger')}</div></div>`;}
function gallery(){return `${section('Mi galería','Imágenes y clips guardados únicamente en este equipo.')}<div class="toolbar">${btn('Importar archivo','mediaImport')}${btn('Capturar ventana','chooseScreenshot')}${btn('Grabar clip (máx. 60 s)','chooseRecording')}</div><div class="grid three">${(state.media||[]).map(m=>`<div class="card">${m.exists?(m.kind==='image'?`<img class="gallery-media" src="${esc(m.url)}" alt="${esc(m.name)}">`:`<video class="gallery-media" src="${esc(m.url)}" controls preload="metadata"></video>`):'<p>Archivo no encontrado. Restaura también la carpeta media.</p>'}<p>${esc(m.name)}</p>${btn('Exportar archivo','mediaExport',m.id,'quiet')}</div>`).join('')}</div>`;}
let recorder=null,recordStream=null,recordTimer;
async function chooseSource(record){
 if(recorder){toast('Termina la grabación actual primero.');return;}
 const result=await window.ranked.action('mediaSources');if(!result.ok){toast(result.error);return;}
 modal(`<h2>${record?'Grabar un clip':'Capturar una ventana'}</h2><p>Elige qué ventana o pantalla quieres guardar en tu galería local.</p>${record?'<label><input id="capture-audio" type="checkbox"> Incluir audio del sistema (todas las aplicaciones)</label><p class="muted small">Máximo 60 segundos, 720p. No se graba el micrófono. Grabar puede consumir recursos adicionales.</p>':''}<div class="source-grid">${result.sources.map(x=>`<button class="button source" data-action="${record?'startRecording':'takeScreenshot'}" data-value="${esc(x.id)}"><img src="${esc(x.thumbnail)}" alt=""><span>${esc(x.name)}</span></button>`).join('')}</div>`);
}
async function startRecording(id){
 const audio=$('#capture-audio')?.checked||false;
 const selected=await window.ranked.action('mediaRecordSelect',{id,audio});if(!selected.ok){toast(selected.error);return;}
 try{
  recordStream=await navigator.mediaDevices.getDisplayMedia({video:{width:{ideal:1280,max:1280},height:{ideal:720,max:720},frameRate:{ideal:30,max:30}},audio});
  const chunks=[];recorder=new MediaRecorder(recordStream,{mimeType:'video/webm;codecs=vp8',videoBitsPerSecond:2500000});
  recorder.ondataavailable=e=>{if(e.data.size)chunks.push(e.data);};
  recorder.onstop=async()=>{clearTimeout(recordTimer);recordStream.getTracks().forEach(t=>t.stop());recorder=null;$('#recording-status')?.remove();const buffer=await new Blob(chunks,{type:'video/webm'}).arrayBuffer();if(await action('mediaRecordSave',buffer))toast('Clip guardado en tu galería');};
  recordStream.getVideoTracks()[0].onended=()=>{if(recorder?.state==='recording')recorder.stop();};
  recorder.start(1000);recordTimer=setTimeout(()=>{if(recorder?.state==='recording')recorder.stop();},60000);$('#modal').close();
  const indicator=document.createElement('div');indicator.id='recording-status';indicator.innerHTML='<span>● Grabando clip · máximo 60 s</span><button class="button" data-action="stopRecording">Detener y guardar</button>';document.body.append(indicator);
 }catch(e){recordStream?.getTracks().forEach(t=>t.stop());recorder=null;await window.ranked.action('mediaRecordCancel');toast('No se pudo grabar: '+e.message);}
}
window.ranked.onStopRecording(()=>{if(recorder?.state==='recording')recorder.stop();});
const renderers={overview,updates,ranks,focus,stats,quests,achievements,projects,shop,admin,profile,journal,friends,settings};
function render(){if(!state)return;BannerTheme.apply(state.bannerGif||(state.cosmetics.banner?bannerUrl(state.cosmetics.banner):null));renderNavigation();setSpeed(document.body,state.settings.nameSpeed);document.body.classList.toggle('light',state.settings.theme==='light');const info=pages.find(p=>p[0]===page);$('#page-title').textContent=page==='overview'?state.name:page==='friends'||page==='admin'?info[2]:info[1];document.body.classList.toggle('dashboard-page',page==='overview');document.querySelectorAll('#nav button').forEach(b=>b.classList.toggle('active',b.dataset.page===page));$('#content').innerHTML=renderers[page]();lastFull=Date.now();header();bindForms();document.querySelectorAll('img').forEach(img=>img.addEventListener('error',()=>{img.style.visibility='hidden';},{once:true}));}
let headerPhoto, headerName;
function updateAvatar(){
 const button=$('#avatar');
 if(headerPhoto===state.avatar && headerName===state.name)return;
 headerPhoto=state.avatar;
 headerName=state.name;
 button.setAttribute('aria-label','Abrir mi perfil');
 button.textContent=state.name.slice(0,1).toUpperCase();
 if(!state.avatar)return;
 const img=new Image();
 img.alt='';
 img.onerror=()=>img.remove();
 img.src=state.avatar;
 button.append(img);
}
function header(){const b=$('#bridge-pill');b.textContent=state.connected?'● Puente conectado':'○ Puente sin conectar';b.classList.toggle('good',state.connected);$('#pause').textContent=state.paused?'Reanudar':'Pausar';updateAvatar();$('#footer-status').textContent=state.reason;const warning=state.saveError||state.nativeError||state.bridgeError||state.warning;$('#alert').innerHTML=warning?`<div class="note error-note">${esc(warning)}</div>`:'';}
function update(next){const previousSocial=state?.social;state=next;if(page==='friends'&&!$('#modal').open&&next.social?.logged&&JSON.stringify(previousSocial)!==JSON.stringify(next.social))render();header();if(document.hidden)return;const editing=['INPUT','TEXTAREA','SELECT'].includes(document.activeElement.tagName)||$('#modal').open;if(!editing&&Date.now()-lastFull>10000&&!['admin','settings','projects','journal','profile','achievements','shop','friends','ranks'].includes(page)){render();return;}if($('#live-timer'))$('#live-timer').textContent=clock(state.session?.seconds);if($('#live-status'))$('#live-status').textContent=state.reason;if($('#status-dot'))$('#status-dot').classList.toggle('on',state.active);if($('#live-session-xp'))$('#live-session-xp').textContent='+'+fmt(state.session?.xp)+' XP';if($('#live-project')&&state.connected)$('#live-project').textContent=state.bridge.name||'Premiere · sin proyecto';}
function bindForms(){
 for(const form of document.querySelectorAll('[data-auth]'))form.onsubmit=async event=>{
  event.preventDefault();
  const button=event.submitter||form.querySelector('button');
  const resend=button.value==='resend';
  if(resend&&!form.elements.email.reportValidity())return;
  button.disabled=true;
  try{
   const result=await window.ranked.action(resend?'resend':form.dataset.auth,resend?{email:form.elements.email.value}:Object.fromEntries(new FormData(form)));
   if(!result.ok){toast(result.error);return;}
   state=result.state;render();
   if(result.confirmation)toast('Revisa tu correo para confirmar la cuenta y después inicia sesión.');
  }finally{button.disabled=false;}
 };
 bindTrial();
 if($('#settings-form'))$('#settings-form').onsubmit=async e=>{e.preventDefault();const f=new FormData(e.target),v=Object.fromEntries(f);for(const k of ['tray','startup','notifications','sound'])v[k]=f.has(k);if(await action('settings',v))toast('Ajustes guardados');};
 if($('#profile-form'))$('#profile-form').elements.nameSpeed.onchange=e=>setSpeed($('#profile-card'),e.target.value);
 if($('#profile-form'))$('#profile-form').onsubmit=async e=>{e.preventDefault();if(await action('settings',Object.fromEntries(new FormData(e.target))))toast('Perfil actualizado');};
 if($('#post-form'))$('#post-form').onsubmit=async e=>{e.preventDefault();if(await action('post',new FormData(e.target).get('text')))toast('Entrada guardada en este equipo');};
 if($('#achievement-search'))$('#achievement-search').oninput=e=>{search=e.target.value;const pos=e.target.selectionStart;render();$('#achievement-search').focus();$('#achievement-search').setSelectionRange(pos,pos);};
}
document.addEventListener('click',async e=>{const b=e.target.closest('button');if(!b)return;if(b.dataset.page){navigate(b.dataset.page);return;}if(b.dataset.filter){filter=b.dataset.filter;render();return;}if(b.dataset.shopFilter){shopFilter=b.dataset.shopFilter;render();return;}const a=b.dataset.action,v=b.dataset.value;if(!a)return;
 if(a==='followEditor'){
  const row=state.social.rows.find(r=>r.id===v);
  await action('follow',{id:v,following:!row.following});return;
 }
 if(a==='messageEditor'){
  modal(`<form id="message-form" class="stack"><h2>Mensaje privado</h2><textarea name="body" required maxlength="1000" placeholder="Escribe tu mensaje"></textarea><button class="button primary">Enviar</button></form>`);
  $('#message-form').onsubmit=async event=>{
   event.preventDefault();const button=event.target.querySelector('button');button.disabled=true;
   try{if(await action('message',{id:v,body:new FormData(event.target).get('body')}))$('#modal').close();}
   finally{button.disabled=false;}
  };return;
 }
 if(a==='extraBadges'){
  const extra=b.closest('.profile-badges').querySelector('.extra-badges');
  extra.hidden=!extra.hidden;
  b.setAttribute('aria-expanded',String(!extra.hidden));
  b.setAttribute('aria-label',extra.hidden?'Mostrar más insignias':'Ocultar insignias adicionales');
  return;
 }
 if(a==='chooseRecording'||a==='chooseScreenshot'){await chooseSource(a==='chooseRecording');return;}
 if(a==='startRecording'){await startRecording(v);return;}
 if(a==='takeScreenshot'){if(await action('mediaScreenshot',v)){$('#modal').close();toast('Captura guardada');}return;}
 if(a==='stopRecording'){if(recorder?.state==='recording')recorder.stop();return;}
 if(a==='editProject'){const p=state.projectInfo[v];modal(`<h2>${esc(p.name||v)}</h2><form id="project-form" class="stack"><label>Notas del proyecto<textarea name="notes">${esc(p.notes||'')}</textarea></label><label>Tarifa específica (${state.settings.currency}/h)<input type="number" min="0" max="100000" step="0.01" name="rate" value="${p.rate??''}" placeholder="Usar tarifa general"></label><button type="submit" class="button primary">Guardar proyecto</button></form>`);$('#project-form').onsubmit=async ev=>{ev.preventDefault();if(await action('project',{key:v,...Object.fromEntries(new FormData(ev.target))})){$('#modal').close();toast('Proyecto actualizado');}};return;}
 if(a==='deletePost'){if(!confirm('¿Eliminar esta entrada de tu diario local?'))return;}
 if(a==='endSession'){if(!confirm('¿Terminar la sesión actual? El seguimiento iniciará otra cuando vuelvas a editar.'))return;}
 if(a==='card'||a==='recap'){const el=$(a==='card'?'#profile-card':'#recap-card');el.scrollIntoView({block:'center'});await new Promise(r=>setTimeout(r,100));const r=el.getBoundingClientRect();await action('capture',{x:Math.round(r.x),y:Math.round(r.y),width:Math.round(r.width),height:Math.round(r.height),name:a});return;}
 if(await action(a,v)){if(a==='installBridge')modal('<h2>Puente instalado</h2><p>Guarda tu proyecto y reinicia Premiere cuando te convenga. Después abre <b>Ventana → Complementos UXP → Ranked Pro Bridge</b>.</p><p class="muted">No se cerró ni se modificó tu proyecto.</p>');if(a==='chest')toast(state.events[0]?.text||'Cofre abierto');}
});
const badgeTip=document.createElement('div');
badgeTip.className='badge-tooltip';
badgeTip.hidden=true;
document.body.append(badgeTip);
function showBadgeTip(event){
 const medal=event.target.closest('[data-badge-detail]');
 if(!medal){badgeTip.hidden=true;return;}
 badgeTip.textContent=medal.dataset.badgeDetail;
 badgeTip.hidden=false;
 const rect=medal.getBoundingClientRect();
 badgeTip.style.left=Math.max(8,Math.min(rect.left,innerWidth-badgeTip.offsetWidth-8))+'px';
 badgeTip.style.top=(rect.bottom+badgeTip.offsetHeight+12<innerHeight?rect.bottom+7:Math.max(4,rect.top-badgeTip.offsetHeight-7))+'px';
}
for(const event of ['pointerover','focusin'])document.addEventListener(event,showBadgeTip);
for(const event of ['pointerout','focusout','scroll','click'])document.addEventListener(event,()=>badgeTip.hidden=true,true);
document.addEventListener('keydown',e=>{if(e.key==='Escape')badgeTip.hidden=true;});
window.ranked.onUpdate(update);window.ranked.onToast(e=>{toast(e.title+' · '+e.text);});
document.addEventListener('visibilitychange',async()=>{if(!document.hidden){state=await window.ranked.snapshot();render();showReleaseNotes();}});
window.ranked.snapshot().then(s=>{state=s;render();showReleaseNotes();}).catch(e=>{$('#content').textContent='No se pudo cargar Ranked Pro: '+e.message;});
